include "root" {
  path   = find_in_parent_folders("root.hcl")
  expose = true
}

terraform {
  source = "${get_parent_terragrunt_dir("root")}/..//modules/aws-vpc-private/"
}

locals {
  account = read_terragrunt_config(find_in_parent_folders("account.hcl"))
}

inputs = {
  vpc_cidr           = "10.60.0.0/16"
  s3_allowed_buckets = ["rhino-ai-agents-runs", "prod-${include.root.locals.aws_region}-starport-layer-bucket"]
  interface_endpoints = ["ssm", "ssmmessages", "ec2messages", "ecr.api", "ecr.dkr", "logs", "autoscaling"]
  tags               = local.account.locals.tags
}

# Lab copy of terraform/root.hcl. The real one uses S3 (rhinohealth-terraform-state); we use a local file.
locals {
  account = read_terragrunt_config(find_in_parent_folders("account.hcl"))
}

remote_state {
  backend = "local"
  config = {
    path = "${get_parent_terragrunt_dir()}/.state/${path_relative_to_include()}/terraform.tfstate"
  }
  generate = { path = "backend.tf", if_exists = "overwrite_terragrunt" }
}

inputs = {
  tags = local.account.locals.tags
}

include "root" {
  path = find_in_parent_folders("root.hcl")
}

terraform {
  source = "${get_parent_terragrunt_dir("root")}/..//modules/fake-pool/"
}

dependency "vpc" {
  config_path  = "../core-services/vpc"
  mock_outputs = { private_subnets = ["10.0.0.0/18"] } # used only while vpc has no state yet
  mock_outputs_allowed_terraform_commands = ["plan", "validate"]
}

inputs = {
  subnet_ids = dependency.vpc.outputs.private_subnets
  sizes      = { lite = "m8i.xlarge", full = "m8i.2xlarge", wide = "m8i.4xlarge" }
}
